<?php require_once __DIR__.'/includes/auth.php';require_login(['admin','hod']);$rows=db()->query("SELECT c.*,GROUP_CONCAT(l.full_name ORDER BY l.full_name SEPARATOR ' | ') lecturers FROM courses c LEFT JOIN course_lecturers cl ON cl.course_id=c.id LEFT JOIN lecturers l ON l.id=cl.lecturer_id GROUP BY c.id ORDER BY c.level,c.semester,c.course_code")->fetchAll();$pageTitle='Course Catalogue | IFT';require __DIR__.'/includes/header.php';?><body class="portal-page"><header class="portal-header"><div class="portal-brand"><img src="assets/naits-logo.png"><div><strong>IFT Result Tracking</strong><span>Course Catalogue</span></div></div><a class="portal-back" href="<?=current_user()['role']==='hod'?'hod-dashboard.php':'admin-dashboard.php'?>">← Dashboard</a></header><main class="portal-main"><div class="page-title"><div><span class="kicker">COURSE CATALOGUE</span><h1>IFT Courses &amp; Lecturers</h1><p>40 courses: 5 courses in each semester for each level. Every course has two assigned lecturers.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Code</th><th>Course</th><th>Level</th><th>Semester</th><th>Assigned Lecturers</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['course_code'])?></strong></td><td><?=e($r['course_title'])?></td><td><?=e($r['level'])?></td><td><?=e($r['semester'])?></td><td><?=e($r['lecturers'])?></td></tr><?php endforeach;?></tbody></table></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>
